public class ContactPhoneCleanup {

    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        if (contactIds == null || contactIds.isEmpty()) {
            return new Map<Id, String>();
        }

        // Fetch only the fields we need
        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
        ];

        // Normalise every non-blank phone: strip everything that is not a digit or '+'
        List<Contact> toUpdate = new List<Contact>();
        for (Contact c : contacts) {
            if (String.isNotBlank(c.Phone)) {
                c.Phone = c.Phone.replaceAll('[^0-9+]', '');
                toUpdate.add(c);
            }
        }

        if (toUpdate.isEmpty()) {
            return new Map<Id, String>();
        }

        // Single DML, allOrNone = false so one bad record doesn't block the rest
        List<Database.SaveResult> results = Database.update(toUpdate, false);

        // Collect failures: Id → first error message
        Map<Id, String> errors = new Map<Id, String>();
        for (Database.SaveResult sr : results) {
            if (!sr.isSuccess()) {
                List<Database.Error> errs = sr.getErrors();
                if (!errs.isEmpty()) {
                    errors.put(sr.getId(), errs[0].getMessage());
                }
            }
        }

        return errors;
    }
}
```

