        if (cutoff == null) {
            return 0;
        }

        Integer totalClosed = 0;

        for (List<Opportunity> chunk : [
            SELECT Id, StageName
            FROM Opportunity
            WHERE IsClosed = false
              AND CloseDate < :cutoff
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = 'Closed Lost';
            }
            update chunk;
            totalClosed += chunk.size();
        }

        return totalClosed;
    }
