public class StaleOpportunityCloser {

    /**
     * Closes stale open opportunities whose CloseDate is strictly before the given cutoff.
     * Uses a SOQL for-loop (list form) so at most one 200-record chunk is in memory at a time.
     *
     * @param cutoff  Opportunities with CloseDate on or after this date are left alone.
     * @return        Number of opportunities set to Closed Lost.
     */
    public static Integer closeStale(Date cutoff) {
        Integer count = 0;

        for (List<Opportunity> chunk : [
            SELECT Id
            FROM Opportunity
            WHERE IsClosed = false
              AND CloseDate < :cutoff
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = 'Closed Lost';
            }
            update chunk;
            count += chunk.size();
        }

        return count;
    }
}
