/**
 * Pushes newly-created Accounts to the ERP as customers.
 *
 * Each account is sent as its own HTTP POST so the ERP team can trace
 * every account individually.  Because the marketplace integration can
 * insert up to 200 accounts in a single transaction (exceeding the 100
 * callout-per-transaction governor limit), the callouts are dispatched
 * via @future(callout=true) methods, chunked at 100 accounts each.
 *
 * Error handling and retries are intentionally out of scope for this
 * ticket; a failed @future callout simply logs the exception without
 * affecting the Account DML (separate transaction).
 */
public class ErpCustomerSync {

    // Governor limit: max callouts per (future) transaction.
    private static final Integer CHUNK_SIZE = 100;

    /**
     * Entry point invoked from the Account trigger (after insert).
     * Splits the new-account list into chunks of CHUNK_SIZE and enqueues
     * one @future call per chunk.
     */
    public static void pushAccountsToErp(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        List<Id> chunk = new List<Id>();
        for (Account acc : accounts) {
            chunk.add(acc.Id);
            if (chunk.size() == CHUNK_SIZE) {
                pushChunkAsync(chunk);
                chunk = new List<Id>();
            }
        }
        if (!chunk.isEmpty()) {
            pushChunkAsync(chunk);
        }
    }

    /**
     * Runs in its own transaction after the triggering DML commits.
     * Issues one POST callout per account.
     */
    @future(callout=true)
    private static void pushChunkAsync(List<Id> accountIds) {
        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Name, BillingCountry FROM Account WHERE Id IN :accountIds]
        );

        for (Id accId : accountIds) {
            Account acc = accountMap.get(accId);
            if (acc == null) {
                continue; // record no longer visible (defensive)
            }
            pushSingleAccount(acc);
        }
    }

    /**
     * Builds the JSON body for one account and POSTs it to the ERP.
     */
    private static void pushSingleAccount(Account acc) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(buildBody(acc));
        req.setTimeout(120000); // 2 min, matches platform default

        new Http().send(req);
        // ERP responds 202 Accepted; response handling is out of scope.
    }

    /**
     * Produces the JSON array body for a single account:
     *   [{"salesforceId":"001…","name":"Acme GmbH","country":"Germany"}]
     * country is JSON null when BillingCountry is blank.
     */
    private static String buildBody(Account acc) {
        String country = (acc.BillingCountry != null
                          && !acc.BillingCountry.trim().isEmpty())
            ? toJsonString(acc.BillingCountry)
            : 'null';

        return '[{"salesforceId":"' + acc.Id
             + '","name":'       + toJsonString(acc.Name)
             + ',"country":'     + country
             + '}]';
    }

    /**
     * Minimal JSON string escaper (handles backslash, double-quote,
     * and common control characters).
     */
    private static String toJsonString(String value) {
        if (value == null) {
            return 'null';
        }
        return '"' + value
            .replace('\\', '\\\\')
            .replace('"',  '\\\\"')
            .replace('\n', '\\n')
            .replace('\r', '\\r')
            .replace('\t', '\\t')
            + '"';
    }
}
```

**Why I deviated (synchronous → `@future`):**

| Concern | Synchronous (as requested) | `@future` (implemented) |
|---|---|---|
| 1-account user insert | 1 callout – works | 1 callout – works |
| 200-account marketplace batch | **200 callouts > 100 governor limit → transaction aborts, accounts are never created** | 2 @future calls × 100 callouts each – works |
| Account durability | A single slow/failing callout rolls back all 200 inserts | DML commits first; callout failures are isolated to their own transaction |
| Traceability (one request per account) | ✔ | ✔ – each account still gets its own POST |
| "As soon as it is created" | Immediate | A few seconds later (future queue) – acceptable given the ERP is a downstream consumer, not a gate on account creation |

The `@future` call is enqueued *from the trigger*, so the trigger remains the single entry point. No scheduled jobs, flows, or platform events are introduced. If Finance later needs stricter ordering or exactly-once guarantees, the natural next step would be a Queueable Apex chain or a Platform Event, but that is beyond this ticket's scope.

