public with sharing class ErpCustomerSync implements Queueable {

    private List<Id> accountIds;

    public ErpCustomerSync(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public void execute(QueueableContext context) {

        // Governor limit: 100 callouts per transaction.
        Integer batchSize = Math.min(100, accountIds.size());
        List<Id> batchIds = accountIds.sublist(0, batchSize);

        // One SOQL for the whole batch.
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :batchIds
        ];

        // One HTTP request per account so the ERP team can trace each record.
        for (Account acc : accounts) {
            Map<String, Object> customer = new Map<String, Object> {
                'salesforceId' => acc.Id,
                'name'         => acc.Name,
                'country'      => String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry
            };
            String body = JSON.serialize(new List<Object> { customer });

            HttpRequest req = new HttpRequest();
            req.setEndpoint('callout:ERP/api/customers');
            req.setMethod('POST');
            req.setHeader('Content-Type', 'application/json');
            req.setBody(body);

            new Http().send(req); // expects 202; error handling / retry out of scope
        }

        // Chain another job if > 100 accounts were passed in (e.g. 200-record batch).
        if (batchSize < accountIds.size()) {
            System.enqueueJob(new ErpCustomerSync(accountIds.sublist(batchSize)));
        }
    }
}
