public class AccountRatingService {

    private static final Set<String> CLOSED_STAGES = new Set<String>{
        'Closed Won', 'Closed Lost'
    };

    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Asynchronously recalculates the Rating on a set of Accounts based on
     * their current open opportunities.
     *
     * @param accountIds  Unique set of Account Ids to recalculate.
     */
    public static void recalculate(Set<Id> accountIds) {
        // --- One bulk SOQL: fetch every open opp for the requested accounts ---
        List<Opportunity> openOpps = [
            SELECT Id,
                   AccountId,
                   StageName,
                   Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND StageName NOT IN :CLOSED_STAGES
        ];

        // --- Group opportunities by parent account (in memory, no extra SOQL) ---
        Map<Id, List<Opportunity>> oppsByAccount = new Map<Id, List<Opportunity>>();
        for (Opportunity opp : openOpps) {
            if (!oppsByAccount.containsKey(opp.AccountId)) {
                oppsByAccount.put(opp.AccountId, new List<Opportunity>());
            }
            oppsByAccount.get(opp.AccountId).add(opp);
        }

        // --- Determine rating per account ---
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            List<Opportunity> accountOpps = oppsByAccount.get(accountId);

            String rating;
            if (accountOpps == null || accountOpps.isEmpty()) {
                rating = 'Cold';
            } else {
                Boolean hasLargeOpen = false;
                for (Opportunity opp : accountOpps) {
                    if (opp.Amount != null && opp.Amount >= HOT_THRESHOLD) {
                        hasLargeOpen = true;
                        break;
                    }
                }
                rating = hasLargeOpen ? 'Hot' : 'Warm';
            }

            accountsToUpdate.add(new Account(Id = accountId, Rating = rating));
        }

        // --- One bulk DML: update all accounts in a single statement ---
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
